// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    bytes4 internal constant IERC165_ID = 0x01ffc9a7;
    bytes4 internal constant IAccessControl_ID = 0x7965db0b;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        vm.assume(interfaceId != IERC165_ID && interfaceId != IAccessControl_ID);

        bool refResult = c.supportsInterface(interfaceId);
        assertTrue(refResult == false);
    }
}
